def select_study_queue(cards: tuple[Card, ...], today: date, settings: SchedulerSettings) -> StudyQueue:
    learning_cards = tuple(
        card for card in cards
        if is_due_learning(card, today)
    )
    learning_cards = sorted(
        learning_cards,
        key=lambda card: (card.due_date, card.id)
    )

    review_cards = tuple(
        card for card in cards
        if is_due_review(card, today)
    )
    review_cards = sorted(
        review_cards,
        key=lambda card: (-overdue_priority(card, today), card.due_date, card.id)
    )
    review_cards = review_cards[:settings.daily_review_limit]

    new_cards = tuple(
        card for card in cards
        if is_due_new(card, today)
    )
    new_cards = sorted(
        new_cards,
        key=lambda card: (card.due_date, card.id)
    )
    new_cards = new_cards[:settings.daily_new_limit]

    return StudyQueue(learning_cards, review_cards, new_cards)

