    if card.state == CardState.SUSPENDED:
        return card

    today = reviewed_at.date()
    original_state = card.state
    original_id = card.id
    original_history = card.history

    if original_state in (CardState.NEW, CardState.LEARNING):
        scheduled_card = schedule_new_or_learning(card, grade, today, settings)
    elif original_state == CardState.REVIEW:
        scheduled_card = schedule_review(card, grade, today, settings)
    else:
        raise DomainError(f"Invalid card state: {original_state}")

    leech_suspended_card = suspend_leech(scheduled_card, settings)

    new_history = original_history + (
        ReviewEvent(
            card_id=original_id,
            reviewed_at=reviewed_at,
            grade=grade,
            seconds=max(seconds, 0),
            state_before=original_state
        ),
    )

    return dataclasses.replace(
        leech_suspended_card,
        history=new_history
    )

